package portfolio.capstone;
import java.sql.*; import java.util.*;
public final class StudentDao { public List<Student> findAll() throws SQLException { List<Student> rows=new ArrayList<>(); String sql="SELECT student_id, registration_number, first_name, last_name FROM students ORDER BY student_id"; try(Connection c=DatabaseUtil.open(); PreparedStatement p=c.prepareStatement(sql); ResultSet r=p.executeQuery()){while(r.next()) rows.add(new Student(r.getInt(1),r.getString(2),r.getString(3),r.getString(4)));} return rows; } public void insert(Student s) throws SQLException { String sql="INSERT INTO students(registration_number,first_name,last_name) VALUES(?,?,?)"; try(Connection c=DatabaseUtil.open(); PreparedStatement p=c.prepareStatement(sql)){p.setString(1,s.getRegistrationNumber());p.setString(2,s.getFirstName());p.setString(3,s.getLastName());p.executeUpdate();} } }
